"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[2029],{1333(e){e.exports=JSON.parse('{"title":"Tanstack Router\uc758 Signal\uae30\ubc18 \ub9ac\ud329\ud1a0\ub9c1","date":"2026-04-07","coverUrl":"/kudzu-based-bench/assets/notion/77a5a669fc1ac3b3.png","html":"<h1 data-notion-block-id=\\"336e548d-8a8e-8088-9ad0-ca6c718192d9\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"33be548d-8a8e-80e2-9f5b-cbad03f807ee\\" id=\\"33be548d-8a8e-80e2-9f5b-cbad03f807ee\\">Tanstack Router\uc758 Signal\uae30\ubc18 \ub9ac\ud329\ud1a0\ub9c1</h2><a href=\\"https://tanstack.com/blog/tanstack-router-signal-graph\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/blog/tanstack-router-signal-graph</a><p data-notion-block-id=\\"336e548d-8a8e-800e-b279-ca781e8e2e63\\">Tanstack Router\uc758 router \uad00\ub828 \uac12 \uacc4\uc0b0\uc744 \uad6c\uc870\ud654 \ub124\ube44\uac8c\uc774\uc158 \ud0d0\uc0c9 \uc791\uc5c5\ub7c9\uc774 \uac10\uc18c\ub418\uc5c8\ub2e4\ub294 \ub9ac\ud329\ud1a0\ub9c1\uc758 \uacfc\uc815\uc744 \ub2f4\uc740 \uae00\uc785\ub2c8\ub2e4. Signal\uc744 \ud1b5\ud574 \uc57d\uac04\uc758 React/Vue \uc6a9\ub7c9\uc774 \uc544\uc8fc \uc57d\uac04 \uc0c1\uc2b9\ud55c\ub370\uc5d0 \ube44\ud574 \ub124\ube44\uac8c\uc774\uc158 \uc791\uc5c5\ub7c9\uc774 \ub300\ud3ed \uac10\uc18c\ud588\uc73c\ubbc0\ub85c \uacbd\uc6b0\uc5d0 \ub530\ub77c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub9cc\ub4dc\ub294 \uacbd\uc6b0\uc5d0 Signal\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \uace0\ub824\ud574\ubd10\ub3c4 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uc560\ud50c\ub9ac\ucf00\uc774\uc158 \ub808\ubca8\uc5d0\uc11c React\uc640 Signal\uc744 \ud568\uaed8 \uc4f0\ub294 \uac83\uc740 \ubcc4\uac1c \ubb38\uc81c\uc785\ub2c8\ub2e4(<a href=\\"https://ones-to-watch.ethansup.net/news/post/1ade548d-8a8e-8033-98a3-d8ad96c244aa#1b1e548d-8a8e-800d-b0cf-c0319aa35c71\\">Signal\uc744 React\uc5d0\uc11c \uc4f0\ub294\uac8c \uc88b\uc740\uac00?</a>). <a href=\\"https://willybrauner.com/journal/signal-the-push-pull-based-algorithm\\">Signal\uc758 push-pull \ubaa8\ub378</a>\uacfc React\uc758 \uc2a4\ucf00\uc904\ub9c1 \ubaa8\ub378\uc774 \uadfc\ubcf8\uc801\uc73c\ub85c \ub2e4\ub974\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"336e548d-8a8e-80f9-9088-e7020729a50e\\" id=\\"336e548d-8a8e-80f9-9088-e7020729a50e\\">axios, \uacf5\uae09\ub9dd \uacf5\uaca9\uc758 \ub300\uc0c1\uc774 \ub418\ub2e4</h2><a href=\\"https://www.stepsecurity.io/blog/axios-compromised-on-npm-malicious-versions-drop-remote-access-trojan\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.stepsecurity.io/blog/axios-compromised-on-npm-malicious-versions-drop-remote-access-trojan</a><p data-notion-block-id=\\"336e548d-8a8e-8085-b259-d34e42984707\\">axios\uac00 \uacf5\uae09\ub9dd \uacf5\uaca9\uc758 \ub300\uc0c1\uc774 \ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. \uc804\uc5d0 \uacf5\uc720\ub4dc\ub838\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/2c6e548d-8a8e-80b8-b96f-c0656a397504#2cae548d-8a8e-8034-a280-c0782647987d\\">pnpm\uc73c\ub85c \uacf5\uae09\ub9dd \uacf5\uaca9\uc758 \ubc29\ud654\ubcbd \uc138\uc6b0\uae30</a> \uae00\uc774 \uc720\uba85\ud55c \ud328\ud0a4\uc9c0\uac00 \uacf5\uae09\ub9dd \uacf5\uaca9\uc758 \ub300\uc0c1\uc774 \ub418\uc5b4\ub3c4 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \ub2e8\uc5d0\uc11c \ubc29\uc5b4\ucc45\uc774 \ub420 \uc218 \uc788\uc73c\ubbc0\ub85c, \uaf2d \uc5f0\uacb0\ud574\uc11c \uc77d\uc73c\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"336e548d-8a8e-803f-85dc-fdb7f0f370a1\\" id=\\"336e548d-8a8e-803f-85dc-fdb7f0f370a1\\">React \ub9c8\uac1c\uc870\ub97c \ud1b5\ud574 \uc704\uc9c0\uc705 \uc5d0\ub514\ud130 \uc131\ub2a5 \uac1c\uc120\ud558\uae30</h2><a href=\\"https://handlewithcare.dev/blog/making_react_prosemirror_really_really_fast/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://handlewithcare.dev/blog/making_react_prosemirror_really_really_fast/</a><p data-notion-block-id=\\"336e548d-8a8e-8009-9147-dce3c37b2a63\\">React \ucef4\ud3ec\ub10c\ud2b8\uc640 \ud14d\uc2a4\ud2b8 \uc5d0\ub514\ud130 ProseMirror \uc5d4\uc9c4\uc744 \ud1b5\ud569\ud560 \ub54c \ubb34\uc5c7\uc774 \ubb38\uc81c\uc778\uc9c0, \uadf8\ub9ac\uace0 \uc131\ub2a5 \ucd5c\uc801\ud654\ub97c \ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 memoization\ub9cc\uc774 \ubb38\uc81c\uac00 \uc544\ub2c8\uace0, React\uc758 \uc0dd\uba85\uc8fc\uae30\uc640 React\uc758 \uaddc\uce59\uc744 \ub530\ub77c\uc11c, \ub54c\ub85c\ub294 \uaddc\uce59\uc744 \uae68\uba74\uc11c \uc5b4\ub5bb\uac8c \uc131\ub2a5\uc744 \uac1c\uc120\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"336e548d-8a8e-80b4-816c-c9b63b96dbd3\\" id=\\"336e548d-8a8e-80b4-816c-c9b63b96dbd3\\">\uc774\ubbf8\uc9c0 Preload \ubc29\uc2dd \uc120\ud0dd \uac00\uc774\ub4dc</h2><a href=\\"https://macarthur.me/posts/preloading-images/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://macarthur.me/posts/preloading-images/</a><p data-notion-block-id=\\"336e548d-8a8e-807e-9c98-e03d95a68ea5\\">\uc218\ub9ce\uc740 \uc774\ubbf8\uc9c0 \ud504\ub9ac\ub85c\ub529 \ubc29\uc2dd\uc774 \uc788\uace0, \uc5b4\ub5a4 \uc7a5\ub2e8\uc810\uc774 \uc788\ub294\uc9c0 \ucc28\ub840\ucc28\ub840 \ub2e8\uacc4\uc801\uc73c\ub85c \uc124\uba85\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ucd94\uac00\ub85c <a href=\\"https://ones-to-watch.ethansup.net/news/post/1c9e548d-8a8e-8049-b946-df263537c848#1cee548d-8a8e-805e-8edb-f515bf861750\\">\ud06c\ub86c\uc758 \uc774\ubbf8\uc9c0 \uc694\uccad \uc21c\uc11c\ub294 \uc5b4\ub5bb\uac8c \uacb0\uc815\ub418\ub294\uac00</a>\uc640 <a href=\\"https://web.dev/learn/images\\">web.dev\uc758 \uc774\ubbf8\uc9c0 \uc139\uc158</a>, <a href=\\"https://www.debugbear.com/blog/improve-image-delivery\\">Debugbear\uc758 \uc774\ubbf8\uc9c0 \ub85c\ub529 \ucd5c\uc801\ud654</a>\ub97c \uc77d\uc5b4\ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"336e548d-8a8e-800c-a299-ddb625082cb8\\" id=\\"336e548d-8a8e-800c-a299-ddb625082cb8\\">\uc778\uae30\uac00 \ub41c Pretext, \uac00\uc7a5 \uc8fc\ubaa9\ud574\uc57c \ud560 \uac83</h2><a href=\\"https://denodell.com/blog/youre-looking-at-the-wrong-pretext-demo\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://denodell.com/blog/youre-looking-at-the-wrong-pretext-demo</a><p data-notion-block-id=\\"33be548d-8a8e-80fa-b10d-c1aacaa337d4\\">\uc800\ubc88\uc8fc\uc5d0 Pretext\ub77c\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc18c\uac1c\ub418\uba74\uc11c \uc544\uc8fc \ub9ce\uc740 \uc778\uae30\ub97c \uc5bb\uac8c \ub418\uc5c8\ub294\ub370, \uadf8\uac83\uc774 \ud654\ub824\ud55c \ud14d\uc2a4\ud2b8 \ub80c\ub354\ub9c1\uc774\ub098 \uc2e0\uae30\ud55c \ub808\uc774\uc544\uc6c3 \ub80c\ub354\ub9c1\uc774 \uc911\uc694 \uae30\ub2a5\uc774 \uc544\ub2d8\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4. \ub610\ud55c \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\ub77c\uba74 \uc5b4\ub5a4 \uae30\ub2a5\uc5d0 \ucd08\uc810\uc744 \ub9de\ucd94\uace0 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc9c0\ucf1c\ubd10\uc57c \ud558\ub294\uc9c0, \uc774\ub7ec\ud55c \uc811\uadfc \ubc29\uc2dd\uc774 \uc0c8\ub85c\uc6b4 \uc811\uadfc\ubc29\uc2dd\uc774 \uc544\ub2cc\ub370\ub3c4 \uc65c \ub2e4\ub978 \ud14d\uc2a4\ud2b8 \ud3b8\uc9d1\uae30\ub4e4\uc740 \uae30\uc874 \ubc29\uc2dd\uc744 \uc120\ud0dd\ud588\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc774 \uae00\uc744 \uc77d\uc5c8\ub2e4\uba74, <a href=\\"https://ones-to-watch.ethansup.net/news/post/237e548d-8a8e-80c8-8e59-c60afe0411ca#23de548d-8a8e-808e-a08e-ddef6bea0022\\">height \uc560\ub2c8\uba54\uc774\uc158, \ud558\uc9c0 \ub9c8\uc138\uc694</a>\ub3c4 \uac19\uc774 \uc77d\uc73c\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"336e548d-8a8e-805e-b4aa-f56b60da80cc\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"336e548d-8a8e-80bb-a653-fcd97d86ed78\\" id=\\"336e548d-8a8e-80bb-a653-fcd97d86ed78\\">npm workspace \uc81c\ub300\ub85c \uc774\ud574\ud558\uae30</h2><a href=\\"https://wasp.sh/blog/2026/03/25/gentle-intro-npm-workspaces\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://wasp.sh/blog/2026/03/25/gentle-intro-npm-workspaces</a><p data-notion-block-id=\\"336e548d-8a8e-80fb-8acf-faeb6255b2b5\\">npm \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\uac00 \uc65c \ud0c4\uc0dd\ud558\uac8c \ub418\uc5c8\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b8\uc81c \uc88b\uc740\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"336e548d-8a8e-80a3-a10e-d95e52cc4be0\\" id=\\"336e548d-8a8e-80a3-a10e-d95e52cc4be0\\">DOM \uae30\ubc18 \uc2a4\ucf08\ub808\ud1a4 \ub9cc\ub4e4\uae30</h2><a href=\\"https://neciudan.dev/lets-build-dynamic-shimmer-skeletons\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://neciudan.dev/lets-build-dynamic-shimmer-skeletons</a><p data-notion-block-id=\\"33be548d-8a8e-8034-9f3c-d953dd13bb45\\">\uc218\ub3d9\uc73c\ub85c \uc2a4\ucf08\ub808\ud1a4\uc744 \ub9cc\ub4dc\ub294 \ub300\uc2e0 DOM \uae30\ubc18\uc73c\ub85c \uce21\uc815\ud574\uc11c \uc2a4\ucf08\ub808\ud1a4\uc744 \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc73c\ub85c \ubcc0\uacbd\ud574\uc11c \uc720\uc9c0\ubcf4\uc218\ub97c \uc904\uc77c \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"336e548d-8a8e-805f-a270-ed3da200efb2\\" id=\\"336e548d-8a8e-805f-a270-ed3da200efb2\\">React\uc5d0\uc11c SVG \ucea1\uc290\ud654\ud558\uae30</h2><a href=\\"https://julesblom.com/writing/colocated-svg-defs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://julesblom.com/writing/colocated-svg-defs</a><p data-notion-block-id=\\"33be548d-8a8e-80d9-9474-feda4d96f1af\\">\uc2e4\uc6a9\uc801\uc778 \uae00\uc740 \uc544\ub2c8\uc9c0\ub9cc, svg\uc758 \uc2a4\ud399\uacfc React\uc5d0\uc11c \uc778\uc2a4\ud134\uc2a4 \uc0ac\uc6a9\ud560 \ub54c\uc758 \uc8fc\uc758\uc810\uacfc \ud638\uc774\uc2a4\ud305\uc744 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud560\uc9c0\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"336e548d-8a8e-8093-bffc-e30e67958a20\\" id=\\"336e548d-8a8e-8093-bffc-e30e67958a20\\">\uc811\uadfc\uc131 \uac1c\uc120\uc744 \uc5c5\ubb34\uc5d0 \ub179\uc5ec\ubcf4\uae30</h2><a href=\\"https://piccalil.li/blog/applying-accessibility-fixes-with-stealth-for-the-greater-good/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/applying-accessibility-fixes-with-stealth-for-the-greater-good/</a><p data-notion-block-id=\\"33be548d-8a8e-80af-83b0-dca73fd54cd3\\">\uc811\uadfc\uc131\uc774 \uc870\uc9c1 \ub0b4\uc5d0\uc11c \ubb34\uc2dc \ub2f9\ud560 \ub54c\uc758 \uc804\ub7b5\uacfc \uc870\uc9c1 \ubb38\ud654\ub97c \uc5b4\ub5bb\uac8c \uc774\ub04c\uc5b4 \ub098\uac00\uc57c \ud560\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);